function importXml(file){const reader=new FileReader();reader.onload=()=>{const diagnostics=[];const detail=[];try{const text=String(reader.result||'');if(!text.trim())throw new Error('The selected file is empty.');if(!/^\s*<\?xml|^\s*</.test(text))throw new Error('The file does not appear to be XML text.');const xml=new DOMParser().parseFromString(text,'application/xml');const parserError=xml.getElementsByTagName('parsererror')[0];if(parserError)throw new Error('XML parser error: '+(parserError.textContent||'Malformed XML').replace(/\s+/g,' ').trim());const root=xml.documentElement;if(!root)throw new Error('The file has no XML document element.');const rootName=root.localName||root.nodeName;if(rootName.toLowerCase()!=='xbrl')diagnostics.push(`Root element is <${rootName}>. This may be a taxonomy/linkbase file rather than an XBRL instance.`);const xbrli='http://www.xbrl.org/2003/instance';const link='http://www.xbrl.org/2003/linkbase';const contextNodes=[...xml.getElementsByTagNameNS(xbrli,'context')];const unitNodes=[...xml.getElementsByTagNameNS(xbrli,'unit')];const contextIds=new Set(contextNodes.map(c=>c.getAttribute('id')).filter(Boolean));const prefixByNs={};for(const a of [...root.attributes])if(a.name.startsWith('xmlns:'))prefixByNs[a.value]=a.name.slice(6);const knownByNs={};for(const e of state.elements){const ns=state.meta?.schemaNamespace||'';(knownByNs[ns]??=e.prefix);if(e.prefix==='in-gaap')knownByNs[ns]='in-gaap';}const importedContexts=contextNodes.map(c=>{const ent=c.getElementsByTagNameNS(xbrli,'identifier')[0];const per=c.getElementsByTagNameNS(xbrli,'period')[0];const start=per?.getElementsByTagNameNS(xbrli,'startDate')[0]?.textContent||'';const end=per?.getElementsByTagNameNS(xbrli,'endDate')[0]?.textContent||'';const instant=per?.getElementsByTagNameNS(xbrli,'instant')[0]?.textContent||'';const dims=[...c.getElementsByTagNameNS('http://xbrl.org/2006/xbrldi','explicitMember')].map(d=>({axis:d.getAttribute('dimension')||'',member:(d.textContent||'').trim()}));return {id:c.getAttribute('id')||'',entity:ent?.textContent||'',scheme:ent?.getAttribute('scheme')||'',start,end,instant,dimensions:dims};});state.importedContexts=importedContexts;state.importedUnits=unitNodes.map(u=>({id:u.getAttribute('id')||'',measure:u.getElementsByTagNameNS(xbrli,'measure')[0]?.textContent||'',divide:!!u.getElementsByTagNameNS(xbrli,'divide')[0]}));if(!contextNodes.length)diagnostics.push('No XBRL contexts were found. A fact needs a context to say which company and period it belongs to.');if(!unitNodes.length)diagnostics.push('No XBRL units were found. Numeric facts may still be readable, but their measurement could not be confirmed.');const facts=[...root.children].filter(n=>n.namespaceURI&&n.localName&&!['schemaRef','context','unit','footnoteLink'].includes(n.localName));let count=0,unknown=0,noContext=0,missingContext=0,duplicate=0;const unknownConcepts=[];state.priorFacts={};const sourceYears=importedContexts.flatMap(c=>[c.end,c.instant]).filter(Boolean).map(x=>Number(String(x).slice(0,4))).filter(Number.isFinite);const sourceCurrentYear=sourceYears.length?Math.max(...sourceYears):null;const importedCin=importedContexts.map(c=>String(c.entity||'').trim().toUpperCase()).find(Boolean);if(importedCin&&validCin(state.profile.cin)&&importedCin!==String(state.profile.cin).trim().toUpperCase())diagnostics.push(`Imported XML CIN ${importedCin} does not match the current filing CIN ${String(state.profile.cin).trim().toUpperCase()}. The imported values are retained for review, but the filing profile was not overwritten.`);for(const n of facts){const ns=n.namespaceURI||'';if(ns===xbrli||ns===link||ns==='http://www.w3.org/2001/XMLSchema-instance')continue;const prefix=prefixByNs[ns]||knownByNs[ns]||n.prefix||'';const k=prefix?`${prefix}:${n.localName}`:n.localName;const txt=(n.textContent||'').trim();const ctx=n.getAttribute('contextRef')||'';if(ctx&&!contextIds.has(ctx)){missingContext++;detail.push(`Fact ${k} refers to missing context “${ctx}”.`);}if(!ctx)noContext++;const known=state.elements.some(x=>`${x.prefix}:${x.name}`===k);if(!known){unknown++;if(unknownConcepts.length<25)unknownConcepts.push(k);}if(txt){const c=importedContexts.find(x=>x.id===ctx);const factYear=Number(String(c?.end||c?.instant||'').slice(0,4));if(!sourceCurrentYear||factYear===sourceCurrentYear){if(state.prior[k]!==undefined)duplicate++;state.prior[k]=txt;(state.priorFacts[k]??=[]).push({value:txt,contextRef:ctx,context:c||null,unitRef:n.getAttribute('unitRef')||'',decimals:n.getAttribute('decimals')||''});count++;}}}if(unknown)diagnostics.push(`${unknown} fact(s) use concepts that could not be matched exactly to the loaded C&I taxonomy. They were retained in the prior-year comparison data so you can review them.`);if(unknownConcepts.length)detail.push('Unmatched concepts: '+unknownConcepts.join(', '));if(noContext)diagnostics.push(`${noContext} imported fact(s) have no contextRef and therefore cannot be safely associated with a reporting period.`);if(missingContext)diagnostics.push(`${missingContext} fact(s) point to a context ID that does not exist in the XML.`);if(duplicate)diagnostics.push(`${duplicate} duplicate concept value(s) were found. The prior-year comparison keeps the last value in the simple column and retains all imported occurrences under the concept details.`);if(!count)diagnostics.push('No non-empty XBRL facts were found. Check that you selected an instance XML, not an XSD, taxonomy linkbase or validation report.');const importedYears=[...new Set(importedContexts.flatMap(c=>[c.end,c.instant]).filter(Boolean).map(x=>String(x).slice(0,4)))];if(importedYears.length)diagnostics.push(`Source XML reporting years detected: ${importedYears.join(', ')}. The latest/source current-year facts (${sourceCurrentYear||'undetermined'}) were placed into this tool's Previous Year column.`);if(importedContexts[0]){const c=importedContexts[0];state.contexts[0]={...state.contexts[0],id:'C1',entity:state.profile.cin||c.entity||'',scheme:c.scheme||'http://www.mca.gov.in/CIN'};}synchronizeAll();state.importDiagnostics=diagnostics;markDirty();render();showImportDiagnostics(file.name,count,diagnostics,detail,importedContexts.length,unitNodes.length);}catch(e){state.importDiagnostics=[e?.message||String(e)];showImportDiagnostics(file.name,0,state.importDiagnostics,[],0,0);}};reader.readAsText(file)}
function showImportDiagnostics(name,count,diagnostics,detail,contextCount,unitCount){const list=diagnostics.length?`<ul>${diagnostics.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<p class="success">No structural import problems were detected.</p>';const details=detail.length?`<div class="card" style="box-shadow:none"><h3>Technical details</h3><div class="diagnostic-list">${detail.map(x=>`<div>${esc(x)}</div>`).join('')}</div></div>`:'';modal(`<div class="modal-head"><div><h2>Previous-year XML import report</h2><div class="hint">${esc(name)}</div></div><button class="close" onclick="closeModal()">Close</button></div><div class="import-summary"><div><b>${count}</b><span>facts read</span></div><div><b>${contextCount}</b><span>contexts</span></div><div><b>${unitCount}</b><span>units</span></div><div><b>${state.elements.length}</b><span>taxonomy concepts available</span></div></div><div class="card" style="box-shadow:none;margin-top:12px"><h3>${count?'Import completed with review items':'Import could not produce usable prior-year facts'}</h3>${list}</div>${details}<div class="card" style="box-shadow:none"><h3>What happens next?</h3><p class="hint">Matched facts are shown in the <strong>prior-year comparison</strong> column of the relevant filing tabs. Click <strong>Tag / details</strong> on a concept to see its QName and any multiple imported contexts. Unmatched concepts are retained for review rather than silently discarded.</p></div>`)}
function generateXml(){if(!requireProfile())return;const result=runChecks();if(result.errors){modal(`<div class="modal-head"><div><h2>XML generation blocked</h2><div class="hint">${result.errors} validation item${result.errors===1?'':'s'} must be corrected first.</div></div><button class="close" onclick="closeModal()">Close</button></div><div class="card" style="box-shadow:none"><p>Nothing has been removed from your filing. Review the <b>Errors / warnings</b> area, correct the highlighted fields, then generate again.</p></div><div class="modal-actions"><button class="smallbtn primary" onclick="closeModal();state.active='errors';renderNav();renderTabs();render()">Open errors</button></div>`);return;}const xml=buildXbrlXml();if(!xml){toast('XML generation stopped because the filing contains invalid content.');return;}const issues=validateGeneratedXml(xml);if(issues.length){state.errors=issues.map(x=>({rule:'Generated instance structural check',concept:'XML',message:x,correction:'Correct the filing data/context/unit/dimension and generate again.'}));render();modal(`<div class="modal-head"><div><h2>XML generation blocked</h2><div class="hint">The internal MCA/XBRL structural gate found ${issues.length} issue${issues.length===1?'':'s'}.</div></div><button class="close" onclick="closeModal()">Close</button></div><div class="card" style="box-shadow:none"><ul>${issues.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div class="modal-actions"><button class="smallbtn primary" onclick="closeModal()">Close</button></div>`);return;}download(new Blob([xml],{type:'application/xml;charset=utf-8'}),'mca-cni-instance-v13.xml');toast('MCA C&I XBRL instance generated and passed the internal structural gate. Validate it in MCA XBRL Validation Tool V5.1 before filing.');}
function toast(msg){const t=$('toast');t.textContent=msg;t.classList.add('show');clearTimeout(window.__toast);window.__toast=setTimeout(()=>t.classList.remove('show'),2600)}
function restoreProjectFile(data){if(!data||typeof data!=='object')throw new Error('Invalid project object.');const keep={meta:state.meta,elements:state.elements,presentation:state.presentation,calculations:state.calculations,definitions:state.definitions,elrs:state.elrs,rules:state.rules};Object.assign(state,data);Object.assign(state,keep);normalizeState();state.appVersion=APP_VERSION;if(!profileComplete())state.active='dashboard';synchronizeAll();renderNav();renderTabs();render();markDirty();}
$('newFilingTopBtn').onclick=startNewFiling;$('saveBtn').onclick=saveData;$('saveProjectFileBtn').onclick=saveProjectFile;$('importXmlBtn').onclick=()=>$('xmlFile').click();$('xmlFile').onchange=e=>e.target.files[0]&&importXml(e.target.files[0]);$('restoreBtn').onclick=()=>$('projectFile').click();$('projectFile').onchange=e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{const data=JSON.parse(r.result);restoreProjectFile(data);toast(`Project restored. Source format: ${esc(data.appVersion||'legacy')}.`);}catch(err){toast(`Restore failed: ${err?.message||'invalid project file.'}`)}};r.readAsText(f)};$('generateBtn').onclick=generateXml;load();